async function api(url,options={}){const response=await fetch(url,{...options,headers:{Accept:'application/json','X-Workflow-Request':'1',...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...options.headers}});if(!response.ok){let b=await response.json().catch(()=>({}));let err=new Error(typeof b.detail==='string'?b.detail:b.detail?.message||`服务请求失败 (${response.status})`);err.status=response.status;throw err}if(!(response.headers.get('content-type')||'').includes('application/json')){let err=new Error('没有连接Python后端');err.noBackend=true;throw err}return response.json()}
function persist(){if(mode==='demo'){localStorage.setItem(STORE,JSON.stringify(ws));$('#savedState').textContent='✓ 示例已保存到本机'}else $('#savedState').textContent='✓ 已写入服务器'}
let toastTimeout;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function product(id){return ws.products.find(p=>p.id===id)}
function current(){return product(productId)||ws.products[0]}
function scopedProducts(){return productId==='all'?ws.products:ws.products.filter(p=>p.id===productId)}
function scopedTasks(){const ids=new Set(scopedProducts().map(p=>p.id));return ws.tasks.filter(t=>ids.has(t.product_id))}
function selectedTasks(module){return scopedTasks().filter(t=>!module||t.module_code===module)}
function done(t){return ['completed','not_applicable'].includes(t.status)}
function overdue(t){return t.due_date&&t.due_date<today()&&!done(t)}
function blockers(t){const ids=ws.dependencies.filter(d=>d.task_id===t.id).map(d=>d.depends_on_task_id);return ws.tasks.filter(x=>ids.includes(x.id)&&!done(x))}
function evidenceCount(t){return t.evidence?t.evidence.length:Number(t.evidence_count||0)}
function progress(ts){const eligible=ts.filter(t=>t.status!=='not_applicable'),total=eligible.reduce((s,t)=>s+Number(t.weight||1),0),n=eligible.filter(t=>t.status==='completed').reduce((s,t)=>s+Number(t.weight||1),0);return total?Math.round(n/total*100):0}
function person(id){return ws.people.find(p=>p.id===id)}
function ownerChip(id){const p=person(id);return p?`<span class="owner-chip"><span class="avatar">${e(p.display_name.slice(0,1))}</span>${e(p.display_name)}</span>`:'<span class="owner-chip"><span class="avatar missing">?</span>待指定</span>'}
const pill=t=>`<span class="pill ${e(t.status)}">${e(statuses[t.status]||t.status)}</span>`;
const empty=(title,desc='',button='')=>`<div class="empty">${icon('boxes')}<h3>${e(title)}</h3><p>${e(desc)}</p>${button}</div>`;
const button=(label,action,primary=false,attrs='')=>`<button class="btn ${primary?'primary':''}" data-action="${action}" ${attrs}>${label}</button>`;

function makeDemo(){
 const people=[['op','运营示例','运营'],['ads','广告示例','广告'],['supply','供应链示例','供应链'],['design','设计示例','设计'],['product','产品示例','产品'],['finance','财务示例','财务'],['compliance','合规示例','合规'],['service','客服示例','客服']].map(([id,display_name,department])=>({id,display_name,department,role_code:'executor',email:''}));
 const products=[{id:'demo-g11',model:'G11',name:'智能安防摄像头',asin:'B0GXZ848Q1',sku:'G11-US',marketplace:'US',brand:'HOMA',product_type:'智能摄像头',target_launch_date:'2027-02-17',current_stage:'上线准备',currency:'USD',data_source:'sample'}, {id:'demo-capri',model:'S-CK024',name:'摄像头 · 示例项目',asin:null,sku:'DEMO-SCK024',marketplace:'US',target_launch_date:null,current_stage:'产品定义',currency:'USD',data_source:'sample'}, {id:'demo-loom',model:'HOMA Loom',name:'智能音箱 · 示例项目',asin:null,sku:'DEMO-LOOM',marketplace:'US',target_launch_date:null,current_stage:'内容准备',currency:'USD',data_source:'sample'}];
 const tasks=[],dependencies=[];
 products.forEach((p,i)=>{
  const completedKeys=new Set(i===0?['account','roles','brand','account-health','capability','subscription','unit-cost','position','keywords','competitors','category','supply-lead','data-definition','cash-plan']:i===1?['capability','position']:['account','brand','capability','position','keywords','subscription','unit-cost','competitors']);
  catalog.tasks.forEach(row=>{
   const owner=people.find(x=>x.department===row.department);
   const id=`${p.id}-${row.key}`;let status=completedKeys.has(row.key)?'completed':(row.key==='privacy'?'blocked':(['images','certification','forecast','copy'].includes(row.key)?'in_progress':'not_started'));
   if(i===0&&row.key==='budget')status='pending_approval';
   tasks.push({id,product_id:p.id,sop_key:row.key,title:row.title,module_code:row.module,stage_name:catalog.modules.find(x=>x.id===row.module).name,phase:row.phase,department:row.department,status,weight:row.weight,owner_id:(row.sequence%7===0)?null:owner?.id,due_date:p.target_launch_date?dateAdd(p.target_launch_date,row.offset):null,evidence_required:row.evidence_required,approval_required:row.approval_required,acceptance_criteria:row.acceptance_criteria,observation_days:row.observation_days,description:'',revision:1,approval_status:status==='completed'?'approved':null,evidence:status==='completed'||status==='pending_approval'?[{uri:'示例交付物：仅用于体验流程，不代表实际完成。',created_at:new Date().toISOString()}]:[]});
   row.depends_on.forEach(key=>dependencies.push({task_id:id,depends_on_task_id:`${p.id}-${key}`}));
  });
 });
 const queries=[{id:'q1',product_id:'demo-g11',keyword:'indoor security camera',postal_code:'10001',device:'desktop',runs_per_day:4,marketplace:'US'}];
 const rankings=[42,41,39,40,38,36,37,35,34,36,33,34,32,31].map((rank,i)=>({product_id:'demo-g11',keyword:queries[0].keyword,observation_type:'organic',rank_value:rank,observed_at:dateAdd(today(),i-13)+'T10:00:00+08:00',source:'sample'}));
 return {schema:4,products,tasks,dependencies,people,events:[{id:'demo-launch',product_id:'demo-g11',title:'G11 目标上线',event_type:'launch',start_date:'2027-02-17',end_date:null,status:'planned',notes:'项目目标日期，尚未执行'}],queries,rankings,imports:[],records:{sales:[],advertising:[],inventory:[],costs:[]},actions:[],documents:[],evidence_links:[]};
}
async function load(){
 catalog=await fetch('catalog.json').then(r=>r.json());
 try{ws=await api('/api/workspace');mode='server';if(!ws.products.length)productId='all';}
 catch(err){if(err.noBackend||err.status===404){mode='demo';try{const saved=JSON.parse(localStorage.getItem(STORE)||'null');ws=saved?.schema===4?saved:makeDemo()}catch{ws=makeDemo()}}
 else{mode='error';ws={products:[],tasks:[],people:[],dependencies:[],events:[],rankings:[],queries:[],imports:[]};toast('后端读取失败，未自动切换为示例数据。')}}
 const requested=location.hash.slice(1);if(requested&&[...nav.flatMap(x=>x[1].map(y=>y[0])),'settings'].includes(requested))view=requested;
 if(!['overview','workflow','calendar','team','settings','agent'].includes(view)&&productId==='all'&&ws.products.length)productId=ws.products[0].id;
 renderShell();render();
}
function renderShell(){
 $('#navigation').innerHTML=nav.map(([group,items])=>`<div class="nav-label">${group}</div>${items.map(([id,title,ic])=>`<button class="nav-item ${view===id?'active':''}" data-action="navigate" data-view="${id}">${icon(ic)}<span>${title}</span>${id==='workflow'?`<span class="nav-count">${ws.tasks.length}</span>`:''}</button>`).join('')}`).join('');
 $('#productScopeIcon').innerHTML=icon('boxes');$('#searchIcon').innerHTML=icon('search');
 $('#connectionBadge').className='connection '+(mode==='server'?'live':'');$('#connectionBadge').innerHTML=`<i></i>${mode==='server'?'已连接 Python 后端':mode==='error'?'数据服务异常':'示例体验模式'}`;
 $('#storageLabel').textContent=mode==='server'?'服务器工作空间':mode==='demo'?'示例仅保存在当前浏览器':'等待服务恢复';
 $('#modeBanner').className='mode-banner '+(mode==='server'?'live':mode==='error'?'error':'');
 $('#modeBanner').innerHTML=mode==='demo'?`<span>◈</span><span><b>示例体验</b> · 型号、任务状态和成员分工用于演示；操作仅保存到当前浏览器，尚未连接 PostgreSQL。</span><button data-action="navigate" data-view="settings">查看功能边界 →</button>`:mode==='server'?`<span>●</span><span>已连接服务器 · ${ws.products.some(p=>p.data_source==='sample')?'带“示例”的项目来自初始种子数据，请按实际业务建立档案。':'任务与记录来自数据库。'}</span>`:`<span>!</span><span>后端数据读取失败。为避免把故障当成空数据，已暂停显示。</span><button data-action="demo">体验本机示例</button>`;
 $('#footerStatus').textContent=mode==='demo'?'示例数据 · 本机保存 · 外部接口未连接':'记录来源：Python API · 自动采集与外部连接分别核验';
}
function navigate(id){view=id;query='';filterModule='all';filterState='all';filterOwner='all';filterPhase='all';$('#searchInput').value='';if(!['overview','workflow','calendar','team','settings','agent'].includes(id)&&productId==='all'&&ws.products.length)productId=ws.products[0].id;location.hash=id;businessData=null;renderShell();render();$('#sidebar').classList.remove('mobile-open');if(mode==='server'&&['ads','inventory','finance','imports'].includes(id))loadBusiness()}
function render(){
 const module=catalog.modules.find(m=>m.id===view),meta=viewMeta[view]||[view.toUpperCase()+' WORKSPACE',module?.name||view,module?.description||''];
 $('#eyebrow').textContent=meta[0];$('#pageTitle').textContent=meta[1];$('#pageDescription').textContent=meta[2];$('#breadcrumb').textContent=module?.name||nav.flatMap(g=>g[1]).find(x=>x[0]===view)?.[1]||'功能与系统设置';
 $('#productSelect').innerHTML=(['overview','workflow','team','calendar','settings','agent'].includes(view)?`<option value="all">全部产品 · ${ws.products.length} 个型号</option>`:'')+ws.products.map(p=>`<option value="${e(p.id)}">${e(p.model)}${p.data_source==='sample'?' · 示例':''}</option>`).join('');$('#productSelect').value=productId;
 $('#marketBadge').textContent=productId==='all'?'MULTI':current()?.marketplace||'—';$('#scopeCaption').textContent='工作范围：'+(productId==='all'?'全部产品':current()?.model||'未选择');
 $('#pageActions').innerHTML=view==='process'?'':view==='overview'?button(icon('flag')+'流程协作','navigate',true,'data-view="process"')+button(icon('link')+'产品交付清单','navigate',false,'data-view="deliverables"')+button(icon('plus')+'新建产品','new-product',true):view==='deliverables'?button(icon('plus')+'新建工作项','new-task',true):view==='calendar'?button(icon('plus')+'新建活动 / 节点','new-event',true):view==='team'?button(icon('plus')+'登记成员','new-person',true):view==='settings'?button(icon('settings')+'系统升级','upgrade',true):view==='ranking'?button(icon('plus')+'新建监控配置','new-query',true):view==='imports'?button('数据口径与模板说明','import-help'):button(icon('plus')+'新建任务','new-task',true);
 if(mode==='error'){ $('#viewRoot').innerHTML=empty('没有读取到服务器数据','请恢复后端后刷新，或者显式选择示例体验。',button('重新连接','refresh'));return;}
 const renderers={process:()=>window.processUI?.render()||'',deliverables:renderDeliverables,overview:renderOverview,workflow:()=>renderWorkflow(),team:renderTeam,calendar:renderCalendar,ranking:renderRanking,agent:renderAgent,imports:renderImports,settings:renderSettings};
 $('#viewRoot').innerHTML=renderers[view]?renderers[view]():renderModule(module);
 window.processUI?.decorate();
 if(view==='ranking')requestAnimationFrame(drawRanking);
 if($('#aiPanel').classList.contains('open'))updateAIContext();
}
function kpi(title,value,unit,caption,ic,color=''){return `<div class="kpi"><div class="kpi-top">${title}${icon(ic)}</div><div class="kpi-number"><b class="${color}">${value}</b><small>${unit}</small></div><div class="kpi-bottom">${caption}</div></div>`}
function table(tasks,compact=false){
 const filtered=tasks.filter(matches);return `<div class="table-wrap"><table class="task-table"><thead><tr><th style="width:34px"></th><th>任务 / 交付物</th>${compact?'':'<th>板块</th>'}<th>负责人</th><th>截止日期</th><th>状态</th>${compact?'':'<th>依赖 / 证据</th>'}</tr></thead><tbody>${filtered.map(t=>`<tr><td><button class="check-btn ${t.status==='completed'?'checked':''}" data-action="toggle" data-id="${e(t.id)}" aria-label="${e(t.title)}：切换完成状态">${t.status==='completed'?'✓':''}</button></td><td><button class="task-name" data-action="task" data-id="${e(t.id)}">${e(t.title)}</button><span class="task-sub">${e(product(t.product_id)?.model)} · ${e(t.phase||'上线前')}${t.approval_required?' · 需审批':''}</span></td>${compact?'':`<td><span class="pill">${e(catalog.modules.find(m=>m.id===t.module_code)?.name||t.stage_name)}</span></td>`}<td>${ownerChip(t.owner_id)}</td><td class="${overdue(t)?'red':''}">${e(shortDate(t.due_date))}${overdue(t)?' · 逾期':''}</td><td>${pill(t)}</td>${compact?'':`<td><span class="task-sub ${blockers(t).length?'orange':''}">${blockers(t).length?blockers(t).length+' 项前置未完成':'依赖已就绪'} · ${evidenceCount(t)} 条证据</span></td>`}</tr>`).join('')||'<tr><td colspan="7" class="row-empty">没有符合筛选条件的任务</td></tr>'}</tbody></table></div>`;
}
function matches(t){const owner=person(t.owner_id);return (!query||(t.title+' '+product(t.product_id)?.model+' '+owner?.display_name+' '+t.department).toLowerCase().includes(query.toLowerCase()))&&(filterModule==='all'||t.module_code===filterModule)&&(filterState==='all'||(filterState==='overdue'?overdue(t):filterState==='unassigned'?!t.owner_id:t.status===filterState))&&(filterOwner==='all'||t.owner_id===filterOwner)&&(filterPhase==='all'||t.phase===filterPhase)}
function renderOverview(){
 const ps=scopedProducts().filter(p=>!query||(p.model+' '+p.name).toLowerCase().includes(query.toLowerCase())),ts=scopedTasks(),completed=ts.filter(t=>t.status==='completed').length,blocked=ts.filter(t=>t.status==='blocked'),pending=ts.filter(t=>t.status==='pending_approval');
 const priority=ts.filter(t=>!done(t)).sort((a,b)=>(a.status==='blocked'?-2:a.status==='pending_approval'?-1:0)-(b.status==='blocked'?-2:b.status==='pending_approval'?-1:0)||(a.due_date||'9999').localeCompare(b.due_date||'9999')).slice(0,5);
 const depts=[...new Set(ts.map(t=>t.department).filter(Boolean))];
 const milestone=ws.products.filter(p=>p.target_launch_date).sort((a,b)=>a.target_launch_date.localeCompare(b.target_launch_date))[0];
 return `<div class="kpi-strip">${kpi('推进中的产品',ps.length,'个型号',`${catalog.modules.length} 个运营板块 · ${catalog.tasks.length} 项标准 SOP`,'boxes')}${kpi('整体完成进度',progress(ts)+'%','按权重',`${completed} / ${ts.length} 项任务已完成`,'check')}${kpi('当前受阻任务',blocked.length,'项',`${ts.filter(t=>!done(t)&&blockers(t).length).length} 项任务仍有前置依赖`,'flag',blocked.length?'orange':'')}${kpi('等待审核',pending.length,'项',`${ts.filter(t=>!done(t)&&!t.owner_id).length} 项待指定负责人`,'people')}</div>
 <section class="panel"><div class="panel-head"><div><h2>产品全流程矩阵 <span class="label">${ps.length} 个型号</span></h2><p>点击任何一个环节，查看该型号对应的工作清单</p></div><div class="head-actions"><span class="label">全部环节 · 加权进度</span>${button('查看全部任务 '+icon('arrow'),'navigate',false,'data-view="workflow"')}</div></div>
 <div class="table-wrap"><table class="matrix"><thead><tr><th>产品型号 / 阶段</th>${catalog.modules.map(m=>`<th>${e(m.name.replace('与',' / '))}</th>`).join('')}<th>整体完成</th></tr></thead><tbody>${ps.map((p,i)=>{const all=ws.tasks.filter(t=>t.product_id===p.id);return `<tr><td><button class="product-label" data-action="product" data-id="${e(p.id)}"><span class="product-tile ${i===1?'teal':i===2?'sand':''}">${e(p.model.slice(0,4))}</span><span><strong>${e(p.model)}</strong><small>${e(p.current_stage||'准备中')} · ${p.target_launch_date?shortDate(p.target_launch_date):'排期待定'}</small></span></button></td>${catalog.modules.map(m=>{const sub=all.filter(t=>t.module_code===m.id),d=sub.filter(t=>t.status==='completed').length;return `<td><button class="stage-cell ${sub.some(t=>t.status==='blocked')?'blocked':''}" data-action="matrix" data-product="${e(p.id)}" data-module="${m.id}" title="${e(p.model+' / '+m.name)}"><span class="cell-fraction ${d===sub.length&&d?'done':''}">${d} / ${sub.length}</span><div class="mini-progress ${d===sub.length?'complete':''}"><i style="width:${progress(sub)}%"></i></div><span class="stage-num">${sub.some(t=>t.status==='blocked')?'受阻':progress(sub)+'%'}</span></button></td>`}).join('')}<td><strong class="purple" style="font-size:15px">${progress(all)}<small style="font-size:9px">%</small></strong></td></tr>`}).join('')||'<tr><td colspan="11" class="row-empty">创建第一个产品，自动展开79项SOP</td></tr>'}</tbody></table></div>
 <div class="matrix-footer"><span>✓ 完成需满足证据、审批和前置依赖要求</span><span class="legend"><span><i></i>推进中</span><span><i class="dot-green"></i>已完成</span><span><i class="dot-amber"></i>受阻 / 待确认</span></span></div></section>
 <div class="split-grid"><section class="panel"><div class="panel-head"><div><h2>今天，先处理这些</h2><p>按阻塞、待审批和截止日期排序</p></div><button class="text-btn" data-action="navigate" data-view="workflow">全部任务 →</button></div>${table(priority,true)}</section>
 <div><section class="panel"><div class="panel-head"><div><h2>部门协作进度</h2><p>交付完成率与待处理工作</p></div><button class="text-btn" data-action="navigate" data-view="team">查看分工 →</button></div><div class="department-list">${depts.slice(0,6).map(dept=>{const dt=ts.filter(t=>t.department===dept);return `<div class="dept-row"><span class="dept-icon">${icon(dept==='供应链'?'boxes':dept==='设计'?'file':dept==='广告'?'megaphone':'people')}</span><div class="dept-main"><div><span>${e(dept)}</span><span>${progress(dt)}%</span></div><div class="mini-progress"><i style="width:${progress(dt)}%"></i></div></div><span class="dept-tail">${dt.filter(t=>!done(t)).length} 待处理</span></div>`}).join('')}</div><div class="note-row">未指定责任人的任务不视为已分配，团队角色暂不等同登录权限。</div></section>
 ${milestone?`<section class="next-milestone"><div><small>NEXT MILESTONE</small><h3>${e(milestone.model)} · 目标上线</h3><p>${e(milestone.target_launch_date)} · 点击查看完整排期</p></div><button class="text-btn" data-action="navigate" data-view="calendar"><span class="countdown">${Math.max(0,Math.round((new Date(milestone.target_launch_date+'T00:00:00')-new Date(today()+'T00:00:00'))/86400000))}<small> 天 →</small></span></button></section>`:''}</div></div>`;
}
function filters(module){return `<div class="toolbar"><div class="filter-row"><select id="statusFilter" aria-label="按状态筛选"><option value="all">全部状态</option>${Object.entries(statuses).map(([k,v])=>`<option value="${k}" ${filterState===k?'selected':''}>${v}</option>`).join('')}<option value="overdue" ${filterState==='overdue'?'selected':''}>仅逾期</option><option value="unassigned" ${filterState==='unassigned'?'selected':''}>待指定负责人</option></select><select id="ownerFilter" aria-label="按负责人筛选"><option value="all">全部负责人</option>${ws.people.map(p=>`<option value="${p.id}" ${filterOwner===p.id?'selected':''}>${e(p.display_name)}</option>`).join('')}</select><select id="phaseFilter" aria-label="按阶段筛选"><option value="all">全部阶段</option>${catalog.phases.map(p=>`<option ${filterPhase===p?'selected':''}>${p}</option>`).join('')}</select><span class="detail-count">${selectedTasks(module).filter(matches).length} 项任务</span></div><div class="segmented"><button data-action="layout" data-layout="table" class="${layout==='table'?'active':''}">清单视图</button><button data-action="layout" data-layout="board" class="${layout==='board'?'active':''}">状态看板</button></div></div>`}
function board(tasks){const filtered=tasks.filter(matches),groups=[['not_started','待开始'],['in_progress','进行中 / 受阻'],['pending_approval','待审批'],['completed','已完成 / 不适用']];return `<div class="board">${groups.map(([code,name])=>{const ts=filtered.filter(t=>t.status===code||(code==='in_progress'&&t.status==='blocked')||(code==='completed'&&t.status==='not_applicable'));return `<section class="board-column"><div class="board-header"><strong>${name}</strong><span>${ts.length}</span></div>${ts.map(t=>`<article class="board-card" data-action="task" data-id="${e(t.id)}" tabindex="0" role="button"><div class="card-module">${e(product(t.product_id)?.model)} / ${e(t.department||'待分工')}</div><h4>${e(t.title)}</h4><div class="card-meta">${ownerChip(t.owner_id)}<span>${shortDate(t.due_date)}</span></div>${t.status==='blocked'?'<div class="task-sub orange">受阻 · 打开任务登记解除条件</div>':''}</article>`).join('')||'<div class="row-empty">暂无任务</div>'}</section>`}).join('')}</div>`}
function renderWorkflow(module){const ts=selectedTasks(module),p=progress(ts);return `${!module?`<div class="kpi-strip">${kpi('当前任务',ts.length,'项',`${catalog.tasks.length} 项标准SOP，可增补自定义任务`,'check')}${kpi('已完成',ts.filter(t=>t.status==='completed').length,'项',`加权进度 ${p}%`,'flag','green')}${kpi('交付与审批',ts.filter(t=>t.status==='pending_approval').length,'待审核','完成按钮由证据、依赖与审批共同约束','people')}${kpi('待确认责任',ts.filter(t=>!done(t)&&!t.owner_id).length,'项','负责人可在任务详情中分配','clock', 'orange')}</div>`:''}
 ${!module?`<div class="filter-tabs"><button class="filter-tab ${filterModule==='all'?'active':''}" data-action="module-filter" data-module="all">全部环节</button>${catalog.modules.map(m=>`<button class="filter-tab ${filterModule===m.id?'active':''}" data-action="module-filter" data-module="${m.id}">${e(m.name)}</button>`).join('')}</div>`:''}${filters(module)}${layout==='table'?`<section class="panel">${table(ts)}</section>`:board(ts)}${mode==='server'&&current()&&!scopedTasks().some(t=>t.sop_key)?`<div class="unavailable"><div><strong>当前产品仍使用旧版简表</strong>保留已有记录，可额外建立79项新版SOP。</div>${button('补全新版 SOP','init-sop')}</div>`:''}`}
const moduleNotes={shop:'账户健康、品牌备案和Case尚未连接 Seller Central；此页管理对应工作和交付证据。',listing:'文案、图片、A+和视频以交付清单管理；自动抓取、内容编辑器与版本对比尚未实现。',ads:'支持标准CSV数据和广告任务管理。SP / SB / Display 专项诊断、Amazon Ads API 和自动调价尚未接入。',inventory:'区分可售、预留、在途和不可售。生产采购通过任务跟踪；补货预测与物流API尚未接入。',finance:'支持成本卡与销售、广告数据。退款、税费、结算和期间费用尚未全部接入，不能视为净利润。',service:'以订单、退货、客服和买家反馈清单协作；订单与消息API尚未接入。',compliance:'此处记录工作、材料与核验结果；清单不等同法规判定，具体要求需按产品与站点核实。'};
function renderModule(m){if(!m)return empty('页面不存在');return `<div class="unavailable"><div><strong>本模块：${e(m.subtitle)}</strong>${e(moduleNotes[m.id]||m.description)}</div><span class="pill warning">${mode==='demo'?'示例工作台':'清单与记录'}</span></div>
 ${['ads','inventory','finance'].includes(m.id)?renderDataStats(m.id)+renderBusinessRecords(m.id):''}<section class="panel" style="margin-bottom:18px"><div class="module-intro"><span class="section-number">${icon(m.icon)}</span><div><h3>${e(m.name)} · 当前产品工作流</h3><p>${e(m.description)}</p></div><button class="text-btn" data-action="navigate" data-view="imports" style="margin-left:auto">${['ads','inventory','finance'].includes(m.id)?'导入业务数据 →':'查看数据来源 →'}</button></div><div class="module-tabs"><button class="${filterPhase==='all'?'active':''}" data-action="phase" data-phase="all">全部交付 ${selectedTasks(m.id).length}</button>${catalog.phases.map(p=>`<button class="${filterPhase===p?'active':''}" data-action="phase" data-phase="${p}">${p} ${selectedTasks(m.id).filter(t=>t.phase===p).length}</button>`).join('')}</div></section>${renderWorkflow(m.id)}`}
function renderDataStats(module){
 const records=ws.records||{sales:[],advertising:[],inventory:[],costs:[]},pid=current()?.id,filter=r=>r.product_id===pid;
 let sales=records.sales.filter(filter).filter(r=>r.date>=dateAdd(today(),-29)&&r.date<=today()),ads=records.advertising.filter(filter).filter(r=>r.date>=dateAdd(today(),-29)&&r.date<=today()),stock=records.inventory.filter(filter),cost=records.costs.filter(filter);
 let count=mode==='demo'?null:businessData;
 const hasSales=count?Number(count.sales?.rows)>0:sales.length>0;
 const hasAds=count?Number(count.advertising?.rows)>0:ads.length>0;
 const rev=count?.sales?.revenue??sales.reduce((s,r)=>s+Number(r.ordered_revenue),0),spend=count?.advertising?.spend??ads.reduce((s,r)=>s+Number(r.spend),0),adsales=count?.advertising?.sales??ads.reduce((s,r)=>s+Number(r.sales),0);
 if(module==='ads')return `<div class="kpi-strip">${kpi('广告花费',hasAds?fmt(spend):'—',current()?.currency||'USD',hasAds?'近30天 · 已导入数据汇总':'近30天暂无广告数据','wallet')}${kpi('广告归因销售',hasAds?fmt(adsales):'—',current()?.currency||'USD','不会重复加入总销售额','chart')}${kpi('ACOS',hasAds&&Number(adsales)>0?(Number(spend)/Number(adsales)*100).toFixed(1)+'%':'—','','缺少归因销售时不计算','megaphone')}${kpi('诊断状态','待接入','','报表归因窗口与成熟度尚待校验','shield')}</div>`;
 if(module==='finance')return `<div class="kpi-strip">${kpi('销售额',hasSales?fmt(rev):'—',current()?.currency||'USD',hasSales?'近30天销售汇总，不等于回款':'近30天暂无销售数据','chart')}${kpi('广告花费',hasAds?fmt(spend):'—',current()?.currency||'USD','与总销售分开列示','wallet')}${kpi('成本卡记录',mode==='demo'?cost.length:count?.cost_count??'—','条','按SKU与生效日期保存','file')}${kpi('净利润','待核算','','退款、税费、费用口径不全不计算','shield')}</div>`;
 const latest=stock.sort((a,b)=>b.date.localeCompare(a.date))[0],inv=count?.inventory||latest;
 return `<div class="kpi-strip">${kpi('可售库存',inv?fmt(inv.fulfillable):'—','件',inv?'快照：'+(inv.snapshot_date||inv.date):'尚未导入库存快照','boxes')}${kpi('预留库存',inv?fmt(inv.reserved):'—','件','不计入可售数量','clock')}${kpi('在途库存',inv?fmt(inv.inbound):'—','件','未接收前不等于可售','upload')}${kpi('补货预测','待配置','','需销量基线、交期和安全库存','chart')}</div>`;
}
async function loadBusiness(){if(!current())return;const id=current().id,targetView=view;try{const [data,records]=await Promise.all([api(`/api/products/${id}/operating-summary`),api(`/api/products/${id}/records?kind=${targetView}`)]);data.records=records;if(current()?.id===id&&view===targetView){businessData=data;render()}}catch(err){toast('业务数据未加载：'+err.message)}}
function renderCalendar(){const start=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth(),1),offset=(start.getDay()+6)%7,gridStart=new Date(start);gridStart.setDate(1-offset);const ps=new Set(scopedProducts().map(p=>p.id)),events=ws.events.filter(x=>ps.has(x.product_id));let tasks=scopedTasks().filter(t=>t.due_date&&!done(t));
 return `<section class="panel"><div class="panel-head"><div><h2>${start.getFullYear()}年 ${start.getMonth()+1}月</h2><p>活动、上线、物流节点及任务截止日期</p></div><div class="head-actions">${button('‹','month-prev')}${button('本月','month-now')}${button('›','month-next')}</div></div><div class="table-wrap"><div class="calendar-grid">${['一','二','三','四','五','六','日'].map(d=>`<div class="calendar-week">周${d}</div>`).join('')}${Array.from({length:42},(_,i)=>{const d=new Date(gridStart);d.setDate(gridStart.getDate()+i);const day=isoDate(d),items=[...events.filter(x=>x.start_date<=day&&(x.end_date||x.start_date)>=day).map(x=>({...x,action:'event'})),...tasks.filter(t=>t.due_date===day).map(x=>({...x,action:'task'}))].filter(x=>!query||x.title.includes(query));return `<div class="calendar-day ${d.getMonth()!==start.getMonth()?'other-month':''} ${day===today()?'today':''}"><span class="day">${d.getDate()}</span>${items.slice(0,2).map(x=>`<button class="calendar-event ${x.action==='task'?'task':x.event_type}" data-action="${x.action}" data-id="${e(x.id)}">${e(product(x.product_id)?.model)} · ${e(x.title)}</button>`).join('')}${items.length>2?`<button class="text-btn calendar-overflow" data-action="day-events" data-date="${day}">+ ${items.length-2} 项工作</button>`:''}</div>`}).join('')}</div></div><div class="matrix-footer"><span>紫色：上线 / 节点　橙色：促销活动　灰色：任务截止</span><span>这是项目排期，活动资格和平台档期需另行核实</span></div></section>
 <section class="panel" style="margin-top:18px"><div class="panel-head"><h2>已登记活动与里程碑</h2><span class="label">${events.length} 个节点</span></div><div class="table-wrap"><table class="task-table"><thead><tr><th>活动 / 节点</th><th>产品</th><th>日期</th><th>负责人</th><th>状态</th></tr></thead><tbody>${events.map(x=>`<tr><td><button class="task-name" data-action="event" data-id="${x.id}">${e(x.title)}</button></td><td>${e(product(x.product_id)?.model)}</td><td>${e(x.start_date)}${x.end_date?' ~ '+e(x.end_date):''}</td><td>${ownerChip(x.owner_id)}</td><td><span class="pill">${e({planned:'已排期',in_progress:'进行中',completed:'已完成',cancelled:'已取消'}[x.status]||'已排期')}</span></td></tr>`).join('')||'<tr><td colspan="5" class="row-empty">尚未登记活动</td></tr>'}</tbody></table></div></section>`}
function renderTeam(){const ts=scopedTasks(),pending=ts.filter(t=>t.status==='pending_approval');return `<div class="unavailable"><div><strong>成员分工不等同于身份权限</strong>当前支持责任分配和管理员口令审批；个人登录、部门隔离与角色权限仍待建设。</div><span class="pill warning">权限体系未完成</span></div><div class="toolbar"><div class="segmented"><button class="${teamTab==='workload'?'active':''}" data-action="team-tab" data-tab="workload">团队负载</button><button class="${teamTab==='approval'?'active':''}" data-action="team-tab" data-tab="approval">待审批 ${pending.length}</button></div><span class="detail-count">${ts.filter(t=>!t.owner_id&&!done(t)).length} 项未分配 · 需负责人确认</span></div>${teamTab==='approval'?`<section class="panel">${table(pending)}</section>`:`<div class="people-grid">${ws.people.filter(p=>!query||(p.display_name+p.department).includes(query)).map(p=>{const own=ts.filter(t=>t.owner_id===p.id);return `<article class="panel person-card"><div class="person-title"><span class="avatar">${e(p.display_name.slice(0,1))}</span><div><h3>${e(p.display_name)}</h3><p>${e(p.department)} · ${e({executor:'执行成员',project_owner:'项目负责人',reviewer:'评审成员'}[p.role_code]||p.role_code)}</p></div></div><div class="person-stats"><span><strong>${own.filter(t=>!done(t)).length}</strong><small>待处理</small></span><span><strong>${own.filter(t=>t.status==='completed').length}</strong><small>已交付</small></span><span><strong>${own.filter(overdue).length}</strong><small>已逾期</small></span></div><div class="mini-progress" style="margin:16px 0 12px"><i style="width:${progress(own)}%"></i></div><button class="text-btn" data-action="owner-tasks" data-id="${p.id}">查看其工作清单 →</button></article>`}).join('')}</div>`}`}
function renderRanking(){const ps=new Set(scopedProducts().map(p=>p.id)),queries=ws.queries.filter(q=>ps.has(q.product_id));if(!rankKeyword||!queries.some(q=>q.keyword===rankKeyword))rankKeyword=queries[0]?.keyword||'';const points=ws.rankings.filter(r=>ps.has(r.product_id)&&r.observation_type===rankType&&(!rankKeyword||r.keyword===rankKeyword));return `<div class="unavailable"><div><strong>定时采集器：尚未连接</strong>${mode==='demo'?'下方为模拟自然排名曲线。':'历史观测来自已保存记录，种子观测不等于真实采集。'} 配置任务只保存参数，不会自行开始抓取。</div><span class="pill warning">未运行</span></div><section class="panel"><div class="panel-head"><div><h2>排名观测趋势</h2><p>数值越低越好 · ${mode==='demo'?'模拟数据':'记录数据'}</p></div><div class="filter-row"><select id="rankType" aria-label="排名类型">${[['organic','自然位'],['sponsored','广告位'],['bsr','BSR']].map(([k,v])=>`<option value="${k}" ${rankType===k?'selected':''}>${v}</option>`).join('')}</select><select id="rankKeyword" aria-label="排名关键词">${queries.map(q=>`<option ${rankKeyword===q.keyword?'selected':''}>${e(q.keyword)}</option>`).join('')}</select></div></div>${points.length?'<div class="chart-container"><canvas id="rankingChart" aria-label="排名趋势图"></canvas></div>':empty('此类型还没有观测','自然排名、广告位和BSR不会混用同一条数据。')}<div class="chart-info">${points.length} 个观测 · 固定站点 / 邮编 / 设备 · 曲线仅用于展示，不自动归因到广告或页面修改。</div></section><section class="panel" style="margin-top:18px"><div class="panel-head"><h2>监控配置</h2><span class="label">${queries.length} 条配置</span></div><div class="table-wrap"><table class="task-table"><thead><tr><th>关键词</th><th>站点 / 邮编</th><th>设备</th><th>计划频率</th><th>执行状态</th></tr></thead><tbody>${queries.map(q=>`<tr><td>${e(q.keyword)}</td><td>${e(q.marketplace||'US')} / ${e(q.postal_code)}</td><td>${e(q.device)}</td><td>每日 ${q.runs_per_day} 次</td><td><span class="pill warning">等待采集器</span></td></tr>`).join('')||'<tr><td colspan="5" class="row-empty">暂无配置</td></tr>'}</tbody></table></div></section>`}
function drawRanking(){const c=$('#rankingChart');if(!c)return;const ids=new Set(scopedProducts().map(p=>p.id)),pts=ws.rankings.filter(r=>ids.has(r.product_id)&&r.observation_type===rankType&&(!rankKeyword||r.keyword===rankKeyword)).sort((a,b)=>a.observed_at.localeCompare(b.observed_at));if(!pts.length)return;const w=c.clientWidth,h=c.clientHeight,dpr=devicePixelRatio||1;c.width=w*dpr;c.height=h*dpr;const x=c.getContext('2d');x.scale(dpr,dpr);const pad={l:35,r:20,t:18,b:29},values=pts.map(r=>Number(r.rank_value)),min=Math.max(1,Math.min(...values)-3),max=Math.max(...values)+3;x.font='10px sans-serif';x.fillStyle='#9aa4b4';x.strokeStyle='#eef0f5';for(let i=0;i<5;i++){const y=pad.t+i*(h-pad.t-pad.b)/4;x.beginPath();x.moveTo(pad.l,y);x.lineTo(w-pad.r,y);x.stroke();x.fillText(Math.round(min+(max-min)*i/4),3,y+3)}const xy=pts.map((p,i)=>[pad.l+(pts.length===1?0:i/(pts.length-1))*(w-pad.l-pad.r),pad.t+(p.rank_value-min)/(max-min)*(h-pad.t-pad.b)]);const grad=x.createLinearGradient(0,pad.t,0,h-pad.b);grad.addColorStop(0,'#e9e3fb99');grad.addColorStop(1,'#f9f7ff22');x.beginPath();x.moveTo(xy[0][0],h-pad.b);xy.forEach(p=>x.lineTo(...p));x.lineTo(xy.at(-1)[0],h-pad.b);x.fillStyle=grad;x.fill();x.beginPath();xy.forEach((p,i)=>i?x.lineTo(...p):x.moveTo(...p));x.strokeStyle='#a28cda';x.lineWidth=2.5;x.stroke();xy.forEach((p,i)=>{x.beginPath();x.arc(...p,3,0,Math.PI*2);x.fillStyle='#fff';x.fill();x.strokeStyle='#a28cda';x.lineWidth=2;x.stroke();if(i%Math.ceil(pts.length/7)===0||i===pts.length-1){x.fillStyle='#a1a8b7';x.fillText(shortDate(pts[i].observed_at.slice(0,10)),p[0]-11,h-6)}})}
function findings(){const ts=scopedTasks(),groups=[['blocked','任务已受阻',ts.filter(t=>t.status==='blocked'),'要求主责人明确阻塞原因、解除条件和承诺日期。'],['overdue','任务超过截止日期',ts.filter(overdue),'确认对上线或运营的影响，重新承诺日期并登记原因。'],['owner','工作责任尚未分配',ts.filter(t=>!t.owner_id&&!done(t)),'将未分配任务落实到部门和主责人，确认交付日期。'],['approval','交付等待验收',ts.filter(t=>t.status==='pending_approval'),'核验交付证据和前置依赖，由审批人决定通过或退回。']];return groups.filter(g=>g[2].length).map(([key,title,tasks,action])=>({key,title:`${tasks.length} 项${title}`,tasks,action}))}
function renderAgent(){const fs=findings();return `<div class="unavailable"><div><strong>当前能力：确定性任务检查 + 可配置外部AI问答</strong>下方规则只检查本页产品范围内的工作流，不会编造销售、广告或库存结论。</div><span class="pill info">人工审批</span></div><section class="panel"><div class="panel-head"><div><h2>需要处理的发现</h2><p>范围：${productId==='all'?'全部产品':e(current()?.model)} · ${today()} · 数据来源：${mode==='demo'?'本机示例':'任务数据库'}</p></div><button class="text-btn" data-action="open-ai">问运营 Agent →</button></div>${fs.map(f=>`<article class="finding"><span class="finding-icon">${icon('flag')}</span><div><h3>${e(f.title)}</h3><p>${e(f.action)}</p><div class="evidence">证据：${e(f.tasks.slice(0,3).map(t=>t.title).join(' / '))}${f.tasks.length>3?' …':''}</div></div>${button('生成跟进任务','finding-task',false,`data-key="${f.key}"`)}</article>`).join('')||empty('没有触发当前任务规则','这不代表经营没有风险；广告、库存与利润诊断尚待接入。')}</section>`}
function renderImports(){return `<div class="data-grid">${[['sales','销售数据','销量、销售额、SKU和币种','chart'],['advertising','广告数据','曝光、点击、花费与归因销售','megaphone'],['inventory','库存快照','可售、预留、在途与不可售','boxes'],['costs','单件成本','产品、头程、FBA与其他成本','wallet']].map(([type,title,desc,ic],i)=>`<article class="panel import-card"><span class="section-number">${icon(ic)}</span><h3>${title}</h3><p>${desc}<br>UTF-8 CSV · 单次不超过 10 MB</p><div class="card-actions"><a href="templates/${type}-template.csv" download>下载示例模板 ↗</a>${button('校验并导入','import',false,`data-type="${type}"`)}</div></article>`).join('')}</div><div class="data-health"><span>缺失值 ≠ 0</span><span>同一业务键重复导入覆盖更新</span><span>模板内是示例行，真实导入前请替换</span><span>币种、SKU和ASIN需与产品一致</span></div><section class="panel" style="margin-top:20px"><div class="panel-head"><div><h2>数据导入记录</h2><p>记录来源、有效行、错误行与导入时间</p></div><span class="label">${mode==='demo'?'本机体验':'服务器记录'}</span></div><div class="table-wrap"><table class="task-table"><thead><tr><th>文件 / 日期</th><th>数据类型</th><th>产品</th><th>有效行</th><th>错误行</th><th>处理结果</th></tr></thead><tbody>${ws.imports.filter(r=>productId==='all'||r.product_id===productId).map(r=>`<tr><td>${e(r.filename)}<span class="task-sub">${new Date(r.created_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}</span></td><td>${e({sales:'销售',advertising:'广告',inventory:'库存',costs:'成本'}[r.import_type])}</td><td>${e(product(r.product_id)?.model)}</td><td>${r.row_count}</td><td class="${r.error_count?'red':''}">${r.error_count}</td><td><button class="text-btn" data-action="import-log" data-id="${r.id}">${r.error_count?'查看错误行':'导入成功'} →</button></td></tr>`).join('')||'<tr><td colspan="6" class="row-empty">尚未导入。先选产品，再下载模板、替换示例行并上传校验。</td></tr>'}</tbody></table></div></section>`}
const coverage=[
 ['四大分类交付目录','可交互','按型号列出分类、具体工作项、文件链接与准备情况','文件登记不等于读取内容或获得访问权限；协作节点的资料从流程详情维护'],
 ['产品型号与全流程总览','可交互','多产品矩阵、产品切换、按环节进入工作清单','真实保存需要部署 PostgreSQL 后端'],
 ['店铺 / Listing / 广告 SOP','可交互','79项SOP，筛选、看板、自定义任务和验收标准','平台状态与内容编辑器尚未接入'],
 ['备货 / 库存 / 采购','部分','备货任务、依赖、库存CSV及快照展示','供应链API、补货预测和采购单尚未完成'],
 ['活动与上线排期','可交互','月份日历、新建活动、里程碑与任务截止','不自动获取亚马逊活动资格与档期'],
 ['可点击流程与动态表单','可交互','时间、地点、人员、附件上传、管理员字段配置、指定人员会签/或签/顺序审核','首次使用需设置管理员并启用节点；飞书同步与通用模板编辑器待建设'],
 ['部门与协作','部分','成员登记、责任分配、工作负载和审批队列','流程协作已有个人账户与配置权限；跨产品数据隔离和通知调度尚未实现'],
 ['任务勾选与验收','可交互','证据、前置依赖和审批限制，修改后重新验收','流程节点由指定人员验收；其他经营接口仍需私有访问网关'],
 ['销售 / 广告 / 库存 / 成本','部分','标准CSV校验、导入历史与数据视图','非原始Amazon报表自动映射；利润口径不完整'],
 ['固定页面定时抓取与排名','未接通','监控参数保存、排名类型切换与历史曲线','采集Worker、调度与失败重试尚未部署'],
 ['外部AI与页面上下文','待配置','常驻入口、当前型号和页面范围、显式@跨页','需配置服务端模型；真实模型调用尚未验收'],
 ['自动经营诊断与执行','未接通','逾期、受阻、责任与审批规则；可创建跟进任务','经营诊断、广告调整和效果验证尚未形成闭环'],
 ['GitHub升级与重启','待实测','管理员口令、备份、迁移、重启与代码回滚脚本','静态站点无法执行；完整升级恢复链路待实测']
];
function renderSettings(){return `<section class="panel"><div class="panel-head"><div><h2>需求覆盖与验收清单</h2><p>有入口 ≠ 已接入真实数据，有脚本 ≠ 已通过生产验收</p></div><span class="label">逐项说明 · 不估算完成百分比</span></div><div class="table-wrap"><table class="task-table coverage-table"><thead><tr><th>原始需求</th><th>当前状态</th><th>已经具备</th><th>仍然缺少 / 运行条件</th></tr></thead><tbody>${coverage.map(([name,status,has,lack])=>`<tr><td>${name}</td><td><span class="pill ${status==='可交互'?'completed':status==='未接通'?'blocked':'warning'}">${status}</span></td><td>${has}</td><td>${lack}</td></tr>`).join('')}</tbody></table></div></section><div class="settings-grid"><section class="panel settings-card"><span class="section-number">${icon('settings')}</span><h3 style="margin-top:13px">系统升级</h3><p>从GitHub main分支更新，备份数据库后迁移、重启并检查健康。代码回滚不等于数据库逆向迁移。</p><div class="meta"><span>当前界面版本</span><strong>v0.4 · 运营工作台</strong></div><div class="meta"><span>部署模式</span><strong>${mode==='demo'?'静态示例 / 本机保存':'Python后端'}</strong></div>${button('检查版本与升级','upgrade')}</section><section class="panel settings-card"><span class="section-number">${icon('spark')}</span><h3 style="margin-top:13px">AI与外部连接</h3><p>模型密钥保存在服务器环境变量中。页面只发送当前产品、当前页面及其筛选范围，显式 @全局 才扩大数据范围。</p><div class="meta"><span>外部模型</span><strong>${mode==='demo'?'未连接 · 本地规则回答':'由服务器配置'}</strong></div><div class="meta"><span>Amazon数据接入</span><strong>待接入 SP-API / Ads API</strong></div>${button('查看部署说明','deploy-help')}</section></div>`}
function modal(title,body,foot='',wide=false){$('#modal').classList.toggle('modal-wide',wide);$('#modalContent').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close-btn" data-action="close-modal" aria-label="关闭弹窗">×</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}`;if(!$('#modal').open)$('#modal').showModal()}
function closeModal(){$('#modal').close()}
function ownerOptions(id,emptyLabel='待指定'){return `<option value="">${emptyLabel}</option>`+ws.people.map(p=>`<option value="${e(p.id)}" ${p.id===id?'selected':''}>${e(p.display_name)} / ${e(p.department)}</option>`).join('')}
function productOptions(id){return ws.products.map(p=>`<option value="${e(p.id)}" ${p.id===id?'selected':''}>${e(p.model)}</option>`).join('')}
function formValue(form,name){return form.elements[name]?.value?.trim()||''}
function formObject(form){return Object.fromEntries(new FormData(form))}
function newProduct(){modal('建立产品主档',`<form id="productForm"><div class="alert info">新产品自动创建 ${catalog.tasks.length} 项SOP及前置依赖；所有任务以未开始、待指定负责人起步。</div><div class="form-row"><label class="field">产品型号<input name="model" required maxlength="80" placeholder="例如：G11"></label><label class="field">站点<select name="marketplace">${['US','CA','UK','DE','JP'].map(x=>`<option>${x}</option>`).join('')}</select></label></div><label class="field">产品名称<input name="name" required maxlength="150" placeholder="正式产品名称"></label><div class="form-row"><label class="field">ASIN<input name="asin" maxlength="10" placeholder="可后补"></label><label class="field">SKU<input name="sku" placeholder="可后补"></label></div><div class="form-row"><label class="field">目标上线日期<input type="date" name="target_launch_date"></label><label class="field">币种<select name="currency"><option>USD</option><option>CAD</option><option>GBP</option><option>EUR</option><option>JPY</option></select></label></div><label class="field">产品类型<input name="product_type" placeholder="摄像头、智能音箱等"></label></form>`,button('取消','close-modal')+button('创建产品与SOP','save-product',true))}
async function saveProduct(){const f=$('#productForm');if(!f.reportValidity())return;const b=formObject(f);if(ws.products.some(p=>p.model.toLowerCase()===b.model.trim().toLowerCase()))return toast('此型号已经存在，请切换到已有产品。');if(b.asin&&!/^[A-Z0-9]{10}$/i.test(b.asin))return toast('ASIN应为10位英文字母或数字。');b.target_launch_date=b.target_launch_date||null;b.name=b.name.trim();b.model=b.model.trim();
 try{if(mode==='server'){const created=await api('/api/products',{method:'POST',body:JSON.stringify(b)});await refreshWorkspace(false);productId=created.id;}else{const p={...b,id:uuid(),current_stage:'档案建立',data_source:'manual-local'};ws.products.push(p);const ids={};catalog.tasks.forEach(item=>{const id=uuid();ids[item.key]=id;ws.tasks.push({id,product_id:p.id,sop_key:item.key,module_code:item.module,stage_name:catalog.modules.find(m=>m.id===item.module).name,title:item.title,phase:item.phase,department:item.department,status:'not_started',weight:item.weight,owner_id:null,due_date:p.target_launch_date?dateAdd(p.target_launch_date,item.offset):null,evidence_required:item.evidence_required,approval_required:item.approval_required,acceptance_criteria:item.acceptance_criteria,observation_days:item.observation_days,evidence:[],revision:1,approval_status:null,description:''})});catalog.tasks.forEach(item=>item.depends_on.forEach(key=>ws.dependencies.push({task_id:ids[item.key],depends_on_task_id:ids[key]})));productId=p.id;persist()}closeModal();navigate('workflow');toast('产品与79项SOP已创建，请先确认负责人和节点。')}catch(err){toast(err.message)}}
function newTask(prefill={}){if(!ws.products.length)return newProduct();modal('新建运营任务',`<form id="newTaskForm"><div class="form-row"><label class="field">所属型号<select name="product_id">${productOptions(prefill.product_id||current()?.id)}</select></label><label class="field">运营板块<select name="module_code">${catalog.modules.map(m=>`<option value="${m.id}" ${(prefill.module_code||view)===m.id?'selected':''}>${m.name}</option>`).join('')}</select></label></div><label class="field">任务与交付物<input name="title" required maxlength="300" value="${e(prefill.title||'')}" placeholder="明确需要交付什么"></label><div class="form-row"><label class="field">主责人<select name="owner_id">${ownerOptions(null)}</select></label><label class="field">截止日期<input type="date" name="due_date"></label></div><div class="form-row"><label class="field">工作阶段<select name="phase">${catalog.phases.map(p=>`<option>${p}</option>`).join('')}</select></label><label class="field">主责部门<input name="department" placeholder="例如：运营"></label></div><label class="field">验收标准<textarea name="acceptance_criteria" required placeholder="写清交付物、判定标准和验证方法">${e(prefill.acceptance_criteria||'')}</textarea></label><label class="field">补充说明<textarea name="description">${e(prefill.description||'')}</textarea></label><label class="field"><span><input type="checkbox" name="approval_required" style="width:auto"> 需要审批后才能完成</span></label><input type="hidden" name="finding_key" value="${e(prefill.finding_key||'')}"></form>`,button('取消','close-modal')+button('创建任务','save-new-task',true))}
async function saveNewTask(){const f=$('#newTaskForm');if(!f.reportValidity())return;const b=formObject(f);b.owner_id=b.owner_id||null;b.due_date=b.due_date||null;b.approval_required=f.elements.approval_required.checked;b.evidence_required=true;const key=b.finding_key;delete b.finding_key;
 try{let created;if(mode==='server'){created=await api('/api/tasks',{method:'POST',body:JSON.stringify(b)});await refreshWorkspace(false)}else{created={...b,id:uuid(),status:'not_started',revision:1,weight:1,evidence:[],approval_status:null};ws.tasks.push(created);persist()}if(key){ws.actions=ws.actions||[];ws.actions.push({key,product_id:b.product_id,task_id:created.id});persist()}closeModal();toast('已创建跟进任务。');render()}catch(err){toast(err.message)}}
async function openTask(id){if(mode==='server'&&window.processUI){const t=ws.tasks.find(x=>x.id===id);if(t){productId=t.product_id;navigate('process');await window.processUI.openNode(id);return;}}let task=ws.tasks.find(t=>t.id===id);if(!task)return;try{if(mode==='server'){const detail=await api(`/api/tasks/${id}`);task={...task,...detail.task,evidence:detail.evidence,approvals:detail.approvals};task.approval_status=detail.approvals.find(a=>a.task_revision===task.revision)?.decision||null;}}catch(err){return toast(err.message)}activeTask=task;$('#aiPanel').classList.remove('open');$('#aiPanel').setAttribute('aria-hidden','true');$('#panelBackdrop').classList.remove('hidden');const deps=ws.dependencies.filter(d=>d.task_id===id).map(d=>d.depends_on_task_id),blocked=blockers(task);
 $('#taskPanel').innerHTML=`<div class="side-head"><div><div class="eyebrow">${e(product(task.product_id)?.model)} / ${e(catalog.modules.find(m=>m.id===task.module_code)?.name||task.stage_name)}</div><h2>任务与验收</h2><p>修改任务要求会使旧审批失效；完成任务前再次检查依赖。</p></div><button class="close-btn" data-action="close-panel" aria-label="关闭任务详情">×</button></div><div class="side-body"><form id="taskEditForm"><label class="field">交付任务<input name="title" required value="${e(task.title)}"></label><div class="form-row"><label class="field">负责人<select name="owner_id">${ownerOptions(task.owner_id)}</select></label><label class="field">截止日期<input name="due_date" type="date" value="${e(task.due_date||'')}"></label></div><div class="form-row"><label class="field">状态<select name="status">${Object.entries(statuses).map(([k,v])=>`<option value="${k}" ${task.status===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">主责部门<input name="department" value="${e(task.department||'')}"></label></div><label class="field">验收标准<textarea name="acceptance_criteria">${e(task.acceptance_criteria||'')}</textarea></label><label class="field">描述 / 阻塞原因<textarea name="description" placeholder="阻塞原因、解除条件、观察周期与回滚条件">${e(task.description||'')}</textarea></label><label class="field">前置依赖<select name="dependencies" multiple aria-label="选择前置依赖">${ws.tasks.filter(t=>t.product_id===task.product_id&&t.id!==id).map(t=>`<option value="${e(t.id)}" ${deps.includes(t.id)?'selected':''}>${done(t)?'✓ ':'○ '}${e(t.title)}</option>`).join('')}</select><small>按住 Ctrl / Command 多选；不允许跨产品依赖与循环依赖。</small></label></form>${blocked.length?`<div class="alert">${blocked.length} 项前置未完成：${e(blocked.slice(0,3).map(t=>t.title).join(' / '))}</div>`:''}<div class="side-section-title">交付证据 <span class="label">${evidenceCount(task)} 条</span></div><div>${(task.evidence||[]).map(x=>`<div class="evidence-item">${/^https?:\/\//i.test(x.uri)?`<a href="${e(x.uri)}" target="_blank" rel="noopener noreferrer">${e(x.uri)}</a>`:e(x.uri)}<small>${x.created_at?new Date(x.created_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):''}</small></div>`).join('')||'<div class="detail-count">尚未登记证据，当前版本支持链接与文字说明，文件托管待接入。</div>'}</div><label class="field">补充证据链接 / 验收说明<textarea id="evidenceInput" placeholder="链接、结果说明或可复核的数据依据"></textarea></label>${button('登记证据','add-evidence')}
 ${task.approval_required?`<div class="side-section-title">审批与复核</div><div class="alert info">当前审批：${e({approved:'已批准',rejected:'已退回'}[task.approval_status]||'未批准')} · ${mode==='demo'?'此处是本机模拟审批。':'服务器要求管理员口令，成员角色尚未接入登录认证。'}</div><label class="field">审批意见<input id="approvalComment" placeholder="记录通过依据或退回原因"></label>${mode==='server'?'<label class="field">管理员审批口令<input type="password" id="approvalToken" autocomplete="off" placeholder="只用于本次审批，不保存"></label>':''}<div class="filter-row">${button('退回','reject-task')}${button('批准当前交付','approve-task')}</div>`:''}</div><div class="side-actions">${button('关闭','close-panel')}${button('保存任务','save-task',true)}${task.status!=='completed'?button('检查并完成','complete-task'):''}</div>`;
 $('#taskPanel').classList.add('open');$('#taskPanel').setAttribute('aria-hidden','false');
}
function closePanels(){$('#taskPanel').classList.remove('open');$('#aiPanel').classList.remove('open');$('#taskPanel').setAttribute('aria-hidden','true');$('#aiPanel').setAttribute('aria-hidden','true');$('#panelBackdrop').classList.add('hidden');activeTask=null}
function taskEditData(){const f=$('#taskEditForm');if(!f)return null;const b=formObject(f);b.dependencies=Array.from(f.elements.dependencies.selectedOptions).map(o=>o.value);b.owner_id=b.owner_id||null;b.due_date=b.due_date||null;return b}
function taskHasEdits(){const b=taskEditData(),t=activeTask;if(!b||!t)return false;return ['title','owner_id','due_date','acceptance_criteria','description','department'].some(k=>(b[k]||'')!==(t[k]||''))||JSON.stringify(b.dependencies.slice().sort())!==JSON.stringify(ws.dependencies.filter(d=>d.task_id===t.id).map(d=>d.depends_on_task_id).sort())}
function createsCycle(id,dependencies){const seen=new Set();function visit(key){if(key===id)return true;if(seen.has(key))return false;seen.add(key);return ws.dependencies.filter(d=>d.task_id===key).some(d=>visit(d.depends_on_task_id))}return dependencies.some(visit)}
function validateComplete(t){if(blockers(t).length)throw new Error('前置依赖尚未完成，请先完成或核实不适用的环节。');if(t.evidence_required&&!evidenceCount(t))throw new Error('这项任务需要交付证据，请先登记。');if(t.approval_required&&t.approval_status!=='approved')throw new Error('这项任务需要批准当前版本后才能完成。')}
async function setTaskStatus(id,status){const t=ws.tasks.find(t=>t.id===id);if(status==='completed')validateComplete(activeTask?.id===id?activeTask:t);if(mode==='server'){await api(`/api/tasks/${id}/status`,{method:'PATCH',body:JSON.stringify({status})});await refreshWorkspace(false)}else{t.status=status;t.completed_at=status==='completed'?new Date().toISOString():null;persist()}}
async function toggle(id){if(mode==='server'&&window.processUI){await openTask(id);return;}const t=ws.tasks.find(t=>t.id===id);try{await setTaskStatus(id,t.status==='completed'?'not_started':'completed');render();toast(t.status==='completed'?'任务已标记完成':'任务状态已保存')}catch(err){toast(err.message);openTask(id)}}
async function saveTask(forceComplete=false){const f=$('#taskEditForm');if(!f.reportValidity())return;const b=taskEditData(),id=activeTask.id,status=forceComplete?'completed':b.status;delete b.status;
 try{if(taskHasEdits()){if(createsCycle(id,b.dependencies))throw new Error('依赖会形成循环，请调整后再保存。');if(mode==='server'){await api(`/api/tasks/${id}`,{method:'PATCH',body:JSON.stringify(b)});await refreshWorkspace(false);activeTask={...ws.tasks.find(t=>t.id===id),evidence:activeTask.evidence};}else{const t=ws.tasks.find(t=>t.id===id);Object.assign(t,b,{revision:(t.revision||1)+1,approval_status:null});delete t.dependencies;ws.dependencies=ws.dependencies.filter(d=>d.task_id!==id);b.dependencies.forEach(pid=>ws.dependencies.push({task_id:id,depends_on_task_id:pid}));if(t.status==='completed')t.status='in_progress';activeTask=t;persist()}}
 if(status!==ws.tasks.find(t=>t.id===id).status)await setTaskStatus(id,status);closePanels();render();toast('任务已保存。')}catch(err){toast(err.message);if(forceComplete)openTask(id)}}
async function addEvidence(){if(taskHasEdits())return toast('请先保存任务修改，再登记证据或审批。');const uri=$('#evidenceInput').value.trim();if(!uri)return toast('请填写可核验的证据说明或链接。');try{if(mode==='server'){await api(`/api/tasks/${activeTask.id}/evidence`,{method:'POST',body:JSON.stringify({evidence_type:/^https?:\/\//i.test(uri)?'url':'note',uri})});await refreshWorkspace(false)}else{const t=ws.tasks.find(t=>t.id===activeTask.id);t.evidence=t.evidence||[];t.evidence.push({uri,created_at:new Date().toISOString()});persist()}await openTask(activeTask.id);toast('证据已登记。')}catch(err){toast(err.message)}}
async function approve(decision){if(taskHasEdits())return toast('请先保存任务修改，批准只针对当前已保存的版本。');if(decision==='approved'&&activeTask.evidence_required&&!evidenceCount(activeTask))return toast('缺少交付证据，不能批准。');if(decision==='approved'&&blockers(activeTask).length)return toast('前置依赖未完成，不能批准。');const comment=$('#approvalComment').value.trim();if(!comment)return toast('请填写本次审批依据或退回原因。');try{if(mode==='server'){const token=$('#approvalToken').value;await api(`/api/tasks/${activeTask.id}/approval`,{method:'POST',headers:{'X-Admin-Token':token},body:JSON.stringify({decision,comment})});$('#approvalToken').value='';await refreshWorkspace(false)}else{const t=ws.tasks.find(t=>t.id===activeTask.id);t.approval_status=decision;t.approvals=t.approvals||[];t.approvals.unshift({decision,comment,task_revision:t.revision});persist()}await openTask(activeTask.id);toast(decision==='approved'?'已批准，仍需点击完成任务。':'已记录退回意见。')}catch(err){toast(err.message)}}
function newEvent(){if(!ws.products.length)return newProduct();modal('登记活动与里程碑',`<form id="eventForm"><label class="field">节点名称<input name="title" required maxlength="200" placeholder="活动报名、发货、上线或复盘"></label><div class="form-row"><label class="field">所属型号<select name="product_id">${productOptions(current()?.id)}</select></label><label class="field">类型<select name="event_type"><option value="promotion">促销活动</option><option value="launch">目标上线</option><option value="shipment">物流节点</option><option value="review">复盘会议</option><option value="deadline">报名 / 截止</option></select></label></div><div class="form-row"><label class="field">开始日期<input name="start_date" type="date" required value="${today()}"></label><label class="field">结束日期<input name="end_date" type="date"></label></div><label class="field">负责人<select name="owner_id">${ownerOptions(null)}</select></label><label class="field">准备条件 / 备注<textarea name="notes" placeholder="资格、毛利、预算、库存与审批要求"></textarea></label></form>`,button('取消','close-modal')+button('保存排期','save-event',true))}
async function saveEvent(){const f=$('#eventForm');if(!f.reportValidity())return;const b=formObject(f);if(b.end_date&&b.end_date<b.start_date)return toast('结束日期不能早于开始日期。');b.end_date=b.end_date||null;b.owner_id=b.owner_id||null;try{if(mode==='server'){await api('/api/events',{method:'POST',body:JSON.stringify(b)});await refreshWorkspace(false)}else{ws.events.push({...b,id:uuid(),status:'planned'});persist()}calendarMonth=new Date(b.start_date+'T12:00:00');closeModal();navigate('calendar');toast('活动节点已登记。')}catch(err){toast(err.message)}}
function showEvent(id){const x=ws.events.find(r=>r.id===id);if(x)modal(e(x.title),`<div class="alert info">${e(product(x.product_id)?.model)} · ${e(x.start_date)}${x.end_date?' ~ '+e(x.end_date):''}</div><p style="font-size:12px;color:#768299;white-space:pre-wrap">${e(x.notes||'没有补充说明')}</p><div style="margin-top:16px">${ownerChip(x.owner_id)}</div>`,button('关闭','close-modal'))}
function newPerson(){modal('登记协作成员',`<form id="personForm"><div class="alert">此操作建立责任人目录，不创建可登录的用户账号，也不授予系统权限。</div><div class="form-row"><label class="field">显示名称<input name="display_name" required maxlength="100"></label><label class="field">主责部门<input name="department" required placeholder="运营、广告、供应链等"></label></div><label class="field">联系邮箱<input type="email" name="email" required></label><label class="field">协作角色<select name="role_code"><option value="executor">执行成员</option><option value="project_owner">项目负责人</option><option value="reviewer">评审成员</option></select></label></form>`,button('取消','close-modal')+button('保存成员','save-person',true))}
async function savePerson(){const f=$('#personForm');if(!f.reportValidity())return;const b=formObject(f);try{if(mode==='server'){await api('/api/people',{method:'POST',body:JSON.stringify(b)});await refreshWorkspace(false)}else{if(ws.people.some(p=>p.email===b.email))return toast('这个邮箱已经登记。');ws.people.push({...b,id:uuid()});persist()}closeModal();render();toast('成员已登记，可以在任务中分配。')}catch(err){toast(err.message)}}
function newQuery(){if(!current())return newProduct();modal('配置关键词排名监控',`<form id="queryForm"><div class="alert">保存的是监控参数；定时采集器尚未接通，不会立即开始抓取。</div><label class="field">关键词<input name="keyword" required placeholder="例如：indoor security camera"></label><div class="form-row"><label class="field">邮编<input name="postal_code" value="10001" required></label><label class="field">设备<select name="device"><option value="desktop">Desktop</option><option value="mobile">Mobile</option></select></label></div><div class="form-row"><label class="field">每天计划次数<input type="number" min="1" max="24" name="runs_per_day" value="4"></label><label class="field">最大页数<input type="number" min="1" max="10" name="max_pages" value="3"></label></div></form>`,button('取消','close-modal')+button('保存参数','save-query',true))}
async function saveQuery(){const f=$('#queryForm');if(!f.reportValidity())return;const b=formObject(f);b.runs_per_day=Number(b.runs_per_day);b.max_pages=Number(b.max_pages);b.marketplace=current().marketplace;try{if(mode==='server'){await api(`/api/products/${current().id}/tracking-queries`,{method:'POST',body:JSON.stringify(b)});await refreshWorkspace(false)}else{ws.queries.push({...b,id:uuid(),product_id:current().id});persist()}closeModal();render();toast('配置已保存，等待采集器接入。')}catch(err){toast(err.message)}}
const importSpec={sales:{label:'销售数据',required:['date','sku','units_ordered','ordered_revenue'],ints:['units_ordered'],nums:['ordered_revenue']},advertising:{label:'广告数据',required:['date','campaign_name','impressions','clicks','spend','sales','orders'],ints:['impressions','clicks','orders'],nums:['spend','sales']},inventory:{label:'库存快照',required:['date','sku','fulfillable','reserved','inbound','unsellable'],ints:['fulfillable','reserved','inbound','unsellable'],nums:[]},costs:{label:'单件成本',required:['date','sku','product_cost','first_mile_cost','fba_fee','referral_fee','other_cost'],ints:[],nums:['product_cost','first_mile_cost','fba_fee','referral_fee','other_cost']}};
function openImport(type){if(!current())return newProduct();if(productId==='all'){productId=current().id;render()}importDraft=null;modal('校验并导入 · '+importSpec[type].label,`<div class="alert info">产品：${e(current().model)} · ${mode==='demo'?'数据只写入当前浏览器。':'有效数据写入PostgreSQL。'}<br>模板包含示例行，请替换成实际数据。重复业务键将更新已有数据。</div><form id="importForm"><input name="type" type="hidden" value="${type}"><label class="field">选择 UTF-8 CSV<input id="importFile" type="file" accept=".csv,text/csv" required></label></form><div id="importValidation"></div>`,button('取消','close-modal')+button('校验文件','validate-import',true)+button('导入有效行','commit-import',false,'disabled id="commitImportBtn"'),true)}
function csvRows(text){const rows=[];let row=[],value='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){value+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(value);value=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(value);if(row.some(v=>v.trim()))rows.push(row);row=[];value=''}else value+=c}if(quote)throw new Error('CSV包含未闭合的引号。');if(value||row.length){row.push(value);if(row.some(v=>v.trim()))rows.push(row)}return rows}
function parseImport(type,text,p){if(text.includes('\uFFFD'))throw new Error('文件不是有效的UTF-8编码，请重新导出。');const rows=csvRows(text.replace(/^\uFEFF/,'')),headers=(rows.shift()||[]).map(h=>h.trim()),spec=importSpec[type];if(new Set(headers).size!==headers.length)throw new Error('列名不能重复。');const missing=spec.required.filter(h=>!headers.includes(h));if(missing.length)throw new Error('缺少必填列：'+missing.join(', '));const valid=[],errors=[];rows.forEach((source,i)=>{const line=i+2;try{if(source.length!==headers.length)throw new Error('列数与表头不一致');const row=Object.fromEntries(headers.map((h,j)=>[h,source[j].trim()]));for(const key of spec.required)if(row[key]==='')throw new Error(key+' 不能为空');if(!/^\d{4}-\d{2}-\d{2}$/.test(row.date)||isNaN(new Date(row.date+'T12:00:00'))||isoDate(new Date(row.date+'T12:00:00'))!==row.date)throw new Error('date 必须是有效的 YYYY-MM-DD 日期');for(const key of [...spec.ints,...spec.nums]){const value=row[key].replace(/,/g,'').replace(/^\$/,'');if(!/^(?:\d+)(?:\.\d+)?$/.test(value)||!Number.isFinite(Number(value))||Number(value)<0)throw new Error(key+' 必须是非负数');if(spec.ints.includes(key)&&!Number.isInteger(Number(value)))throw new Error(key+' 必须是整数');row[key]=Number(value)}row.currency=(row.currency||p.currency||'USD').toUpperCase();if(type!=='inventory'&&row.currency!==(p.currency||'USD'))throw new Error('币种与产品主档不一致');if(p.sku&&row.sku&&row.sku!==p.sku)throw new Error('SKU与当前产品不一致');if(p.asin&&row.asin&&row.asin!==p.asin)throw new Error('ASIN与当前产品不一致');valid.push(row)}catch(err){errors.push({line,error:err.message})}});return {headers,rows:valid,errors}}
async function validateImport(){const f=$('#importFile').files[0],type=formValue($('#importForm'),'type');if(!f)return toast('请先选择CSV文件。');if(f.size>10*1024*1024)return toast('文件超过10MB，请拆分后导入。');try{const parsed=parseImport(type,await f.text(),current());importDraft={...parsed,type,file:f,productId:current().id};$('#importValidation').innerHTML=`<div class="alert ${parsed.errors.length?'':'info'}">校验结果：${parsed.rows.length} 行有效 · ${parsed.errors.length} 行错误。<br>点击“导入有效行”后才会保存；错误行不会写入。</div>${parsed.errors.length?`<div class="import-preview"><table class="task-table"><thead><tr><th>行号</th><th>错误原因</th></tr></thead><tbody>${parsed.errors.slice(0,20).map(x=>`<tr><td>${x.line}</td><td>${e(x.error)}</td></tr>`).join('')}</tbody></table></div>`:''}<div class="import-preview"><table class="task-table"><thead><tr>${parsed.headers.map(h=>`<th>${e(h)}</th>`).join('')}</tr></thead><tbody>${parsed.rows.slice(0,5).map(r=>`<tr>${parsed.headers.map(h=>`<td>${e(r[h])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;$('#commitImportBtn').disabled=!parsed.rows.length;}catch(err){importDraft=null;$('#commitImportBtn').disabled=true;$('#importValidation').innerHTML=`<div class="alert error">${e(err.message)}</div>`}}
function recordKey(type,r){return [r.product_id,r.date,...(type==='advertising'?[r.campaign_name,r.entity_name||'']:[r.sku])].join('|')}
async function commitImport(){if(!importDraft?.rows.length)return;const d=importDraft;if(current()?.id!==d.productId)return toast('产品范围已变化，请重新校验。');$('#commitImportBtn').disabled=true;try{if(mode==='server'){const body=new FormData();body.append('import_type',d.type);body.append('file',d.file);await api(`/api/products/${d.productId}/imports`,{method:'POST',body});await refreshWorkspace(false)}else{ws.records=ws.records||{sales:[],advertising:[],inventory:[],costs:[]};const id=uuid(),target=ws.records[d.type];for(const row of d.rows){const record={...row,product_id:d.productId,import_id:id},index=target.findIndex(r=>recordKey(d.type,r)===recordKey(d.type,record));index<0?target.push(record):target.splice(index,1,record)}ws.imports.unshift({id,product_id:d.productId,import_type:d.type,filename:d.file.name,row_count:d.rows.length,error_count:d.errors.length,errors:d.errors,created_at:new Date().toISOString(),status:d.errors.length?'completed_with_errors':'completed'});persist()}closeModal();render();toast(`已导入 ${d.rows.length} 行有效数据。`);importDraft=null}catch(err){toast(err.message);$('#commitImportBtn').disabled=false}}
function importLog(id){const log=ws.imports.find(x=>x.id===id);modal('导入结果 · '+e(log.filename),`<div class="alert info">有效 ${log.row_count} 行 · 错误 ${log.error_count} 行</div>${log.errors?.length?`<table class="task-table"><thead><tr><th>行号</th><th>原因</th></tr></thead><tbody>${log.errors.map(x=>`<tr><td>${x.line}</td><td>${e(x.error)}</td></tr>`).join('')}</tbody></table>`:'<p class="muted">所有已处理的行均通过校验。</p>'}`,button('关闭','close-modal'))}
const scopePrefixes={'@交付清单':'deliverables','@资料':'deliverables','@全局':'global','@驾驶舱':'overview','@流程':'workflow','@店铺':'shop','@页面':'listing','@广告':'ads','@库存':'inventory','@活动':'calendar','@利润':'finance','@售后':'service','@合规':'compliance','@排名':'ranking','@建议':'agent','@导入':'imports','@团队':'team'};
function contextTitle(scope=view){return scope==='global'?'当前产品全部页面':nav.flatMap(g=>g[1]).find(x=>x[0]===scope)?.[1]||catalog.modules.find(m=>m.id===scope)?.name||(scope==='settings'?'功能与系统设置':scope)}
function contextKey(){return [productId,view,view==='deliverables'?[deliveryCategory,deliveryReadiness,deliveryKind].join('|'):'',filterModule,filterState,filterOwner,filterPhase,query,view==='ranking'?rankType+'|'+rankKeyword:'',view==='calendar'?calendarMonth.toISOString().slice(0,7):''].join(':')}
function updateAIContext(){if(!$('#aiContext'))return;$('#aiContext').innerHTML=`<strong>当前范围：${e(productId==='all'?'全部型号':current()?.model)} / ${e(contextTitle())}</strong>默认只使用该页面及当前筛选。跨页请显式输入 @全局、@广告、@库存 等。`;const key=contextKey(),logs=chatLogs[key]||[];$('#aiMessages').innerHTML=logs.length?logs.map(msg=>`<div class="chat-message ${msg.role}">${e(msg.text)}<small>${e(msg.scope)}</small></div>`).join(''):'<div class="chat-message">我会使用当前页面的数据。切换型号、页面或筛选后，对话范围也会切换。<small>'+e(mode==='demo'?'本机规则摘要 · 未连接外部模型':'回答由服务器模型配置决定')+'</small></div>';$('#aiMessages').scrollTop=$('#aiMessages').scrollHeight}
function openAI(){activeTask=null;$('#taskPanel').classList.remove('open');$('#taskPanel').setAttribute('aria-hidden','true');$('#panelBackdrop').classList.remove('hidden');$('#aiPanel').innerHTML=`<div class="side-head"><div><div class="eyebrow">CONTEXT-AWARE ASSISTANT</div><h2>运营 Agent <span class="pill info">${mode==='demo'?'规则预览':'服务端模型'}</span></h2><p>先读证据，再形成可执行的工作。</p></div><button class="close-btn" data-action="close-panel" aria-label="关闭Agent">×</button></div><div class="ai-context" id="aiContext"></div><div class="ai-messages" id="aiMessages" aria-live="polite"></div><form class="ai-form" id="aiForm"><textarea id="aiInput" placeholder="问当前页面，或使用 @全局 跨页面分析…" required></textarea><div><small>不自动修改广告、价格或Listing</small><button class="btn primary" type="submit" id="sendAI">发送 ${icon('arrow')}</button></div></form>`;$('#aiPanel').classList.add('open');$('#aiPanel').setAttribute('aria-hidden','false');updateAIContext();$('#aiInput').focus()}
function localAnswer(scope){
 if(scope==='deliverables')return deliveryLocalAnswer();
 if(scope==='settings')return '当前页面是需求覆盖清单。已具备产品矩阵、79项SOP、任务交付、活动日历和四类CSV交互。Amazon API、定时采集、自动经营诊断与完整角色权限尚未接通。';
 if(scope==='imports'){const records=ws.imports.filter(x=>productId==='all'||x.product_id===productId);return `当前产品范围有 ${records.length} 次导入。${records.length?'最近文件：'+records[0].filename+'，有效 '+records[0].row_count+' 行，错误 '+records[0].error_count+' 行。':'尚未导入数据，不能据此得出销售、广告或库存结论。'}`;}
 if(scope==='ranking'){const pts=ws.rankings.filter(x=>(productId==='all'||x.product_id===productId)&&x.observation_type===rankType&&(!rankKeyword||x.keyword===rankKeyword));return `当前排名筛选下有 ${pts.length} 个${{organic:'自然位',sponsored:'广告位',bsr:'BSR'}[rankType]}观测。${pts.length?'最近记录为 '+pts.at(-1).rank_value+'。':'暂无观测。'} 定时采集器尚未连接。`;}
 if(scope==='calendar'){const month=isoDate(calendarMonth).slice(0,7),events=ws.events.filter(x=>(productId==='all'||x.product_id===productId)&&x.start_date.slice(0,7)===month);return `当前月份 ${month} 已登记 ${events.length} 个活动或里程碑。${events.map(x=>x.start_date+' '+x.title).join('；')||'任务截止日可在日历中展开查看。'}`;}
 const module=catalog.modules.find(m=>m.id===scope)?.id;
 let ts=selectedTasks(module);if(scope===view)ts=ts.filter(matches);
 const pending=ts.filter(t=>!done(t)),blocked=ts.filter(t=>t.status==='blocked'),missing=pending.filter(t=>!t.owner_id),approval=ts.filter(t=>t.status==='pending_approval');return `当前范围共 ${ts.length} 项工作，已完成 ${ts.filter(t=>t.status==='completed').length} 项，受阻 ${blocked.length} 项，待审批 ${approval.length} 项，未分配责任人 ${missing.length} 项。\n${blocked.length?'先核实受阻任务：'+blocked.slice(0,2).map(t=>t.title).join('；')+'。':pending.length?'下一项可跟进：'+pending[0].title+'。':'当前范围没有未完成任务。'}\n这是当前页面数据的规则摘要，尚未调用外部模型，不做经营因果判断。`;
}
async function sendAI(ev){ev.preventDefault();const input=$('#aiInput'),message=input.value.trim();if(!message)return;const prefix=Object.keys(scopePrefixes).find(k=>message.startsWith(k)),scope=prefix?scopePrefixes[prefix]:view,key=contextKey(),label=(productId==='all'?'全部型号':current()?.model)+' / '+contextTitle(scope)+' / '+today();chatLogs[key]=chatLogs[key]||[];chatLogs[key].push({role:'user',text:message,scope:label});input.value='';updateAIContext();$('#sendAI').disabled=true;let answer;
 try{if(mode==='server'&&productId!=='all'){const result=await api('/api/agent/chat',{method:'POST',body:JSON.stringify({product_id:productId,page_id:view==='overview'?'dashboard':view==='process'?'workflow':view,message,conversation_id:conversations[key]||null,filters:{delivery_category:deliveryCategory,delivery_readiness:deliveryReadiness,delivery_kind:deliveryKind,status:filterState,owner_id:filterOwner==='all'?null:filterOwner,module:filterModule,phase:filterPhase,search:query,rank_type:rankType,rank_keyword:rankKeyword,month:isoDate(calendarMonth).slice(0,7)}})});answer=result.answer;conversations[key]=result.conversation_id;}else answer=localAnswer(scope)+(mode==='server'?'\n如需外部模型分析，请先选择一个具体型号。':'');}catch(err){answer='请求未完成：'+err.message+'。没有替换为模拟模型回答。'}chatLogs[key].push({role:'assistant',text:answer,scope:label});if(key===contextKey()&&$('#aiPanel').classList.contains('open'))updateAIContext();if($('#sendAI'))$('#sendAI').disabled=false;}
async function showUpgrade(){modal('系统版本与升级',`<div id="upgradeStatus" class="alert info">正在读取当前版本与服务器配置…</div><div class="update-steps">${['检查GitHub','备份PostgreSQL','构建与迁移','重启服务','健康检查','失败恢复代码'].map(s=>`<span>${s}</span>`).join('')}</div><label class="field">管理员升级口令<input id="updateToken" type="password" autocomplete="off" placeholder="仅用于本次请求"></label><div class="alert">自动升级仅在完整Docker部署中运行。数据库破坏性迁移不能靠代码回滚恢复；升级链路仍需在真实服务器演练。</div>`,button('关闭','close-modal')+button('升级至 main 最新提交并重启','run-upgrade',true,'disabled id="runUpgradeBtn"'));try{const data=await api('/api/system/version');$('#upgradeStatus').textContent=`版本：${data.version} · 提交：${(data.commit||'unknown').slice(0,12)} · ${data.update_enabled?'升级服务已启用':'自动升级未启用'}`;$('#runUpgradeBtn').disabled=!data.update_enabled;}catch{$('#upgradeStatus').className='alert';$('#upgradeStatus').textContent='未连接升级后端：当前在线站点为静态工作台，无法在这里执行服务器升级。';}}
async function runUpgrade(){const token=$('#updateToken').value;if(!token)return toast('请输入管理员升级口令。');if(!confirm('升级将备份数据库、更新代码并重启服务，期间会短暂中断。确认执行？'))return;try{await api('/api/system/update',{method:'POST',headers:{'X-Admin-Token':token}});$('#updateToken').value='';$('#runUpgradeBtn').disabled=true;pollUpgrade(0);}catch(err){$('#upgradeStatus').textContent=err.message}}
async function pollUpgrade(attempt){clearTimeout(pollTimer);if(!$('#modal').open||!$('#upgradeStatus'))return;if(attempt>180){$('#upgradeStatus').textContent='超过自动观察时限，请在服务器核实升级状态后重新检查。';return}try{const r=await api('/api/system/update-status');$('#upgradeStatus').textContent=`${{checking:'检查更新',backing_up:'备份数据库',updating:'更新与构建',restarting:'重启中',rolling_back:'恢复旧代码',succeeded:'升级成功',up_to_date:'已经是最新提交',failed:'升级失败'}[r.status]||r.status} · ${r.detail||r.error||''}`;if(['succeeded','failed','up_to_date'].includes(r.status)){$('#runUpgradeBtn').disabled=false;if(r.status==='succeeded')setTimeout(()=>location.reload(),1500);return}}catch{$('#upgradeStatus').textContent='服务暂时不可用，正在等待重启恢复…'}pollTimer=setTimeout(()=>pollUpgrade(attempt+1),3000)}
async function refreshWorkspace(notify=true){if(mode==='server'){ws=await api('/api/workspace');if(productId!=='all'&&!product(productId))productId='all';}if(notify){renderShell();render();toast(mode==='demo'?'已重新读取本机示例状态。':'已重新读取服务器数据。')}}
async function handleAction(el){const a=el.dataset.action,id=el.dataset.id;
 switch(a){
 case 'delivery-category':deliveryCategory=el.dataset.category;render();break;
 case 'document-new':openProductDocument(id);break;
 case 'document-edit':openProductDocument(el.dataset.task,id);break;
 case 'save-product-document':await saveProductDocument();break;
 case 'document-history':showDocumentHistory(id);break;
 case 'export-deliverables':exportDeliverables();break;
 case 'delivery-help':modal('文件与阶段如何判定', '<div class="alert info">前3列固定为：大分类 → 具体工作项 → 对应文件链接。</div><p class="muted">文件交付项：至少登记一个当前文件或文件夹链接，当前链接均人工标为已准备，且任务通过原有证据、审批和依赖验收后，才显示“文件与阶段已齐”。阶段确认项可直接根据任务完成状态显示“阶段已完成”。缺少资料时不会因为勾了任务就隐藏缺口。更新文件会保留历史版本，并让对应任务重新验收。</p>',button('关闭','close-modal'));break;
 case 'navigate':navigate(el.dataset.view);break;
 case 'product':productId=id;navigate('workflow');break;
 case 'matrix':productId=el.dataset.product;navigate('workflow');filterModule=el.dataset.module;render();break;
 case 'new-product':newProduct();break;case 'save-product':await saveProduct();break;
 case 'new-task':newTask(view==='deliverables'?{module_code:({store:'shop',listing:'listing',advertising:'ads',delivery:'inventory'}[deliveryCategory]||'shop')}:{});break;case 'save-new-task':await saveNewTask();break;
 case 'task':await openTask(id);break;case 'toggle':await toggle(id);break;
 case 'save-task':await saveTask(false);break;case 'complete-task':await saveTask(true);break;
 case 'close-panel':closePanels();break;case 'add-evidence':await addEvidence();break;
 case 'approve-task':await approve('approved');break;case 'reject-task':await approve('rejected');break;
 case 'close-modal':closeModal();break;
 case 'module-filter':filterModule=el.dataset.module;render();break;
 case 'phase':filterPhase=el.dataset.phase;render();break;
 case 'layout':layout=el.dataset.layout;render();break;
 case 'team-tab':teamTab=el.dataset.tab;render();break;
 case 'owner-tasks':navigate('workflow');productId='all';filterOwner=id;render();break;
 case 'new-person':newPerson();break;case 'save-person':await savePerson();break;
 case 'new-event':newEvent();break;case 'save-event':await saveEvent();break;case 'event':showEvent(id);break;
 case 'month-prev':calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()-1,1);render();break;
 case 'month-next':calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+1,1);render();break;
 case 'month-now':calendarMonth=new Date();render();break;
 case 'day-events':{const day=el.dataset.date,ts=scopedTasks().filter(t=>t.due_date===day&&!done(t));modal(day+' · 工作清单',table(ts),button('关闭','close-modal'),true);break;}
 case 'new-query':newQuery();break;case 'save-query':await saveQuery();break;
 case 'open-ai':openAI();break;
 case 'import':openImport(el.dataset.type);break;case 'validate-import':await validateImport();break;case 'commit-import':await commitImport();break;case 'import-log':importLog(id);break;
 case 'import-help':modal('导入口径与限制','<div class="alert info">目前支持标准化CSV模板，不会自动识别各种Amazon原始报表。</div><p class="muted">统一日期 YYYY-MM-DD；金额按产品币种，不跨币种相加；SKU和ASIN归属当前型号。必填值缺失不按0处理；同一日期、SKU（广告为Campaign+对象）覆盖更新。成本是单件金额，不能当期间总费用。</p>',button('关闭','close-modal'));break;
 case 'finding-task':{const f=findings().find(x=>x.key===el.dataset.key);if(!f)return;const existing=(ws.actions||[]).find(x=>x.key===f.key&&productId===x.product_id&&ws.tasks.some(t=>t.id===x.task_id&&!done(t)));if(existing){openTask(existing.task_id);break;}newTask({product_id:f.tasks[0].product_id,module_code:'review',title:'跟进：'+f.title,description:f.action,acceptance_criteria:'关联发现逐项闭环，登记处理证据和复核结果。',finding_key:f.key});break;}
 case 'init-sop':if(current()){await api(`/api/products/${current().id}/workflow`,{method:'POST'});await refreshWorkspace();toast('已补全标准SOP。')}break;
 case 'upgrade':await showUpgrade();break;case 'run-upgrade':await runUpgrade();break;
 case 'deploy-help':modal('真实运行的接入条件','<div class="alert">该在线站点为静态前端，连接真实数据库需要另行部署Python服务。</div><p class="muted">GitHub仓库包含Docker Compose、PostgreSQL迁移与部署说明。模型通过服务器 LLM_API_BASE、LLM_API_KEY、LLM_MODEL 配置，密钥不放在网页中。SP-API、Ads API、采集Worker与完整登录权限尚待建设。</p>',button('关闭','close-modal'));break;
 case 'refresh':window.processUI?.invalidate();if(mode==='error')await load();else await refreshWorkspace();break;
 case 'demo':mode='demo';ws=makeDemo();productId='all';persist();renderShell();render();break;
 }
}
if (typeof document !== 'undefined') {
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action]');if(!el)return;if(el.tagName==='BUTTON')ev.preventDefault();try{await handleAction(el)}catch(err){toast(err.message)}});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){closePanels();$('#sidebar').classList.remove('mobile-open')}if(ev.key==='Enter'&&ev.target.matches('.board-card'))handleAction(ev.target)});
document.addEventListener('submit',ev=>{if(ev.target.id==='aiForm'){sendAI(ev);return;}if(['productForm','newTaskForm','eventForm','personForm','queryForm','taskEditForm','importForm','productDocumentForm'].includes(ev.target.id))ev.preventDefault()});
document.addEventListener('change',ev=>{const id=ev.target.id;if(id==='productSelect'){productId=ev.target.value;businessData=null;render();if(mode==='server'&&['ads','inventory','finance'].includes(view))loadBusiness();}else if(id==='deliveryReadyFilter'){deliveryReadiness=ev.target.value;render()}else if(id==='deliveryKindFilter'){deliveryKind=ev.target.value;render()}else if(id==='statusFilter'){filterState=ev.target.value;render()}else if(id==='ownerFilter'){filterOwner=ev.target.value;render()}else if(id==='phaseFilter'){filterPhase=ev.target.value;render()}else if(id==='rankType'){rankType=ev.target.value;render()}else if(id==='rankKeyword'){rankKeyword=ev.target.value;render()}else if(id==='importFile'){importDraft=null;if($('#commitImportBtn'))$('#commitImportBtn').disabled=true;}});
$('#searchInput').addEventListener('input',ev=>{query=ev.target.value;render()});$('#panelBackdrop').addEventListener('click',closePanels);$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('mobile-open');window.addEventListener('resize',()=>{if(view==='ranking')drawRanking()});
load().catch(err=>{$('#viewRoot').innerHTML=empty('工作台未能加载',err.message);$('#modeBanner').textContent='加载失败，请检查页面资源并刷新。'});

window.addEventListener('hashchange',()=>{const target=location.hash.slice(1);if(target&&target!==view&&[...nav.flatMap(g=>g[1].map(x=>x[0])),'settings'].includes(target))navigate(target)});

}
function renderBusinessRecords(module){const kind={ads:'advertising',inventory:'inventory',finance:'costs'}[module];const rows=mode==='demo'?(ws.records?.[kind]||[]).filter(r=>r.product_id===current()?.id):(businessData?.records||[]);const columns={ads:[['report_date','日期'],['campaign_name','Campaign'],['entity_name','对象'],['spend','花费'],['attributed_sales','归因销售'],['clicks','点击'],['currency','币种']],inventory:[['snapshot_date','快照日期'],['sku','SKU'],['fulfillable','可售'],['reserved','预留'],['inbound','在途'],['unsellable','不可售']],finance:[['effective_date','生效日期'],['sku','SKU'],['product_cost','产品成本'],['first_mile_cost','头程'],['fba_fee','FBA'],['referral_fee','佣金'],['other_cost','其他单件成本'],['currency','币种']]}[module];if(!rows.length)return '';return `<section class="panel" style="margin-bottom:18px"><div class="panel-head"><div><h2>${module==='finance'?'单位成本卡':'已导入记录'}</h2><p>按日期保存，显示最近100行；非完整经营核算</p></div><button class="text-btn" data-action="navigate" data-view="imports">查看导入历史 →</button></div><div class="table-wrap"><table class="task-table"><thead><tr>${columns.map(([k,l])=>`<th>${l}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,100).map(r=>`<tr>${columns.map(([k])=>`<td>${e(r[k]??(k.endsWith('_date')?r.date:k==='attributed_sales'?r.sales:''))}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`}
